def convertNumber(s: str) -> str:
    words = {
        "zero": "0", "one": "1", "two": "2", "three": "3", "four": "4",
        "five": "5", "six": "6", "seven": "7", "eight": "8", "nine": "9",
    }

    res = []
    i, n = 0, len(s)
    while i < n:
        for word, digit in words.items():
            if s.startswith(word, i):      # a number word starts here
                res.append(digit)
                i += len(word)             # jump over the whole word
                break
        else:
            i += 1                         # no word starts here, skip one char

    return ''.join(res)
